export default {"id":"djing-level-6","number":6,"title":"Warp as Beatgrid · Gate C","skillBand":"Textbook","duration":"From the course textbook","summary":"Warping time-stretches audio so clips can sync to Set tempo. Warp off retains original tempo (useful for one-shots and effects). Warp on follows Set tempo for rhythmic material and full songs. 1. Import full track to Deck A or B.","modules":[{"id":"djing-m-6-1","code":"6","title":"Warp as Beatgrid · Gate C","blurb":"Warping time-stretches audio so clips can sync to Set tempo. Warp off retains original tempo (useful for one-shots and effects). Warp on follows Set tempo for rhythmic material and full songs. 1. Import full track to Deck A or B.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"djing-l-o-6","title":"Section overview","blocks":[{"type":"step","title":"overview","blocks":[{"type":"heading","text":"Module 6 — Warp as Beatgrid · Gate C","level":1},{"type":"prose","html":"<strong>Objective:</strong> Make full songs follow Set tempo accurately as deck material.   <strong>Difficulty:</strong> Intermediate craftsmanship — warps must survive end-of-track checks, not only intro downbeats.   <strong>Sources:</strong> Live 12 Manual <em>9. Audio Clips, Tempo, and Warping</em> (Complex / Complex Pro); <em>How-to-DJ</em> §5.1; <em>Foundations of Digital DJing</em> (1.1.1 procedure, formant rationale)."}]}],"minutes":8},{"id":"djing-l-6-1-1","title":"6.1.1 — Warping Protocol for Full Tracks","blocks":[{"type":"step","title":"Definition (Manual)","blocks":[{"type":"prose","html":"Warping time-stretches audio so clips can sync to Set tempo. Warp off retains original tempo (useful for one-shots and effects). Warp on follows Set tempo for rhythmic material and full songs."},{"type":"prose","html":"<strong>Complex</strong> — suitable for mixed material (beats, melodies, textures), including entire songs.   <strong>Complex Pro</strong> — may improve quality on polyphonic or full-song material; Formants control matters when pitch is transposed; both modes can be more CPU-intensive (Manual §9.3.5). Standard includes Complex Pro. Use Complex Pro when Complex produces audible artifacts; it is not cost-free."}]},{"type":"step","title":"Protocol","blocks":[{"type":"list","items":["Import full track to Deck A or B.  ","Locate the true first downbeat transient; set <strong>1.1.1</strong> there (context menu and warp workflow in How-to-DJ and Foundations).  ","Confirm original BPM and warp markers; correct drift where hats or kicks leave the grid.  ","Choose Complex first; switch to Complex Pro if stretch artifacts appear.  ","<strong>End-of-track verification:</strong> scrub or play the last 30–60 seconds — correct intros often fail in outros.  ","Set phrase-ready cue(s); name clip with BPM and cue note.  ","Stress at Set tempos a few BPM above and below native; listen for smear, warble, and transient degradation."],"ordered":true}]},{"type":"step","title":"Multi-track discipline","blocks":[{"type":"prose","html":"Warped clips follow Set tempo by default. The requirement is accurate grids. Auto-warp is a starting estimate; ears and markers determine the result."}]},{"type":"step","title":"Common errors","blocks":[{"type":"list","items":["1.1.1 on a pickup or anacrusis instead of true beat 1  ","Checking only the first 16 bars  ","Complex Pro on all material without audible benefit and with higher CPU cost  ","Using warp to force a blend that should be a cut or an edit  ","Inventing rigid genre BPM rules not supported by sources  "],"ordered":false}]},{"type":"step","title":"Laboratory 6.1.1","blocks":[{"type":"prose","html":"Warp 12 full tracks to show standard. For each: mode used, BPM, 1.1.1 confidence (high/medium/low), end-check pass or fail, CPU note if Pro."},{"type":"prose","html":"<strong>Pass criteria:</strong> At least 10 of 12 pass end-check at Set tempo; explanation of why Pro was or was not needed on two examples."}]}],"minutes":8},{"id":"djing-l-6-2-1","title":"6.2.1 — Tempo Relationships and Artifacts · Gate C","blocks":[{"type":"step","title":"6.2.1 — Tempo Relationships and Artifacts · Gate C","blocks":[{"type":"heading","text":"Tempo relationships","level":3},{"type":"list","items":["Nearby tempos are easier; large jumps require more accurate warps and a clearer musical rationale.  ","Stretch artifacts indicate a quality limit.  ","Phase nudge and small Set tempo moves serve musical alignment under control."],"ordered":false},{"type":"heading","text":"Pair laboratory","level":3},{"type":"prose","html":"Build 8 pairs from the warped library:"},{"type":"table","headers":["Pair type","Goal"],"rows":[["Easy neighborhood","Clean sync feel with accurate warps"],["Slight stretch","Determine when Complex to Pro helps"],["Aggressive stretch","Decide: musical tool, refuse, edit, or different track"]],"caption":null},{"type":"heading","text":"Gate C — self-assessment","level":3},{"type":"list","items":["[ ] 1.1.1 procedure automatic  ","[ ] End-of-track verification habitual  ","[ ] Complex versus Complex Pro chosen with a stated reason  ","[ ] At least 8 of 10 random pulls from the 12-track bank hold grid through a full listen at Set tempo  ","[ ] A deliberately broken warp (1.1.1 shifted by one beat) detected by ear within 8 bars  "],"ordered":false},{"type":"prose","html":"<strong>If criteria are not met:</strong> rebuild the bank; do not proceed to Modules 7–9 with incorrect grids."}]},{"type":"step","title":"Module 6 checkpoint","blocks":[{"type":"list","items":["[ ] Warped bank ready for mixer and transition work  ","[ ] Gate C evidence: bank list and two corrected failure examples  "],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
